package com.djibtout.backend.controller;
import com.djibtout.backend.entity.*;import com.djibtout.backend.repository.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin/categories") public class AdminCategoryController{private final CategoryRepository categories;private final UserRepository users;public AdminCategoryController(CategoryRepository c,UserRepository u){categories=c;users=u;}private boolean admin(Authentication a){return a!=null&&users.findByEmail(a.getName()).map(u->u.getRole()==Role.ADMIN).orElse(false);}@GetMapping public ResponseEntity<?> list(Authentication a){return admin(a)?ResponseEntity.ok(categories.findAllByOrderByDisplayOrderAscNameAsc()):ResponseEntity.status(403).build();}@PostMapping public ResponseEntity<?> create(Authentication a,@Valid @RequestBody Input input){if(!admin(a))return ResponseEntity.status(403).build();Category c=new Category();return save(c,input);}@PutMapping("/{id}") public ResponseEntity<?> update(Authentication a,@PathVariable Long id,@Valid @RequestBody Input input){if(!admin(a))return ResponseEntity.status(403).build();Category c=categories.findById(id).orElse(null);return c==null?ResponseEntity.notFound().build():save(c,input);}@DeleteMapping("/{id}") public ResponseEntity<?> delete(Authentication a,@PathVariable Long id){if(!admin(a))return ResponseEntity.status(403).build();categories.deleteById(id);return ResponseEntity.noContent().build();}private ResponseEntity<?> save(Category c,Input i){String slug=i.slug().trim().toLowerCase(Locale.ROOT);if(categories.existsBySlugAndIdNot(slug,c.getId()==null?-1L:c.getId()))return ResponseEntity.status(409).body("Slug déjà utilisé.");c.setName(i.name().trim());c.setSlug(slug);c.setDisplayOrder(i.displayOrder());c.setActive(i.active());c.setParent(i.parentId()==null?null:categories.findById(i.parentId()).orElse(null));return ResponseEntity.ok(categories.save(c));}public record Input(@NotBlank @Size(max=120) String name,@NotBlank @Pattern(regexp="[a-z0-9-]+") String slug,Long parentId,int displayOrder,boolean active){}}
